function pendingEntry(clip: Clip): TranscriptEntry {
	return {
		role: "caller",
		id: clip.id,
		text: "Voice clip pending transcription…",
		pending: true,
		ts: clip.created / 1000,
	};
}

function renderHistory(entries: TranscriptEntry[] = []): void {
	const history = entries || [];
	const completed = new Set(history.map((entry) => entry.id).filter(Boolean));
	// A transcript in history is the durable completion acknowledgement.
	// Drop its retained audio even if the live transcript frame was lost.
	outbox = outbox.filter((clip) => !completed.has(clip.id));
	updateOutboxUI();
	logEl.textContent = "";
	history.forEach(appendTurn);
	// Preserve optimistic bubbles for clips accepted but not transcribed.
	outbox.forEach((clip) => {
		if (!turnForClip(clip.id)) appendTurn(pendingEntry(clip));
	});
	logEl.scrollTop = logEl.scrollHeight;
}

function playNext() {
	const generation = ++playbackGeneration;
	if (currentUrl) {
		URL.revokeObjectURL(currentUrl);
		currentUrl = null;
	}
	const blob = currentBlob || audioQueue.shift();
	if (!blob) {
		currentBlob = null;
		isPlaying = false;
		statusEl.textContent = idleText;
		statusEl.classList.remove("error");
		return;
	}
	isPlaying = true;
	currentBlob = blob;
	currentUrl = URL.createObjectURL(blob);
	playPending = true;
	player.src = currentUrl;
	player.play().then(
		() => {
			if (generation !== playbackGeneration || currentBlob !== blob) return;
			playPending = false;
		},
		(err) => {
			if (generation !== playbackGeneration || currentBlob !== blob) return;
			playPending = false;
			currentBlob = null;
			// Autoplay rejection is recoverable: keep this clip at the front so
			// the next user gesture retries it instead of silently losing it.
			audioQueue.unshift(blob);
			statusEl.textContent =
				"Audio blocked by the browser — click anywhere on this page once, then it will play (" +
				errorName(err) +
				").";
			statusEl.classList.add("error");
			isPlaying = false;
		},
	);
}

player.addEventListener("ended", () => {
	if (playPending || !currentBlob || player.ended === false) return;
	// Browsers can emit pause immediately before ended when playback is
	// skipped to the end. The current clip stays separate from the queue until
	// ended confirms that it is finished, so this advances exactly once.
	currentBlob = null;
	playNext();
});
// A pause from the exposed controls otherwise leaves isPlaying true forever.
// Keep the current clip in place: a later click resumes it, while a following
// ended event clears it and advances without replaying it from the queue.
player.addEventListener("pause", () => {
	if (!isPlaying || playPending || player.ended || player.paused === false)
		return;
	isPlaying = false;
	statusEl.textContent =
		"Audio paused — click anywhere on this page to resume.";
});
// `ended` used to be the only thing that advanced the queue, so a single
// clip that failed to decode — or the caller pressing pause on the
// exposed controls — wedged playback permanently at "Queued (N waiting)".
player.addEventListener("error", () => {
	if (!isPlaying || playPending || !currentBlob || !player.error) return;
	currentBlob = null;
	playNext();
});
// The status message promises that a page interaction resumes blocked audio.
// Keep that gesture path here rather than relying on a later clip to arrive.
document.addEventListener("click", () => {
	if (isPlaying || !currentBlob) {
		if (!isPlaying && audioQueue.length) playNext();
		return;
	}
	const generation = playbackGeneration;
	playPending = true;
	player.play().then(
		() => {
			if (generation === playbackGeneration && currentBlob) {
				playPending = false;
				isPlaying = true;
			}
		},
		() => {
			if (generation === playbackGeneration && currentBlob) playPending = false;
		},
	);
});

// Rebuilt only when the set of options actually changes, so a select the
// caller has open does not collapse under them on a routine status update.
function fillSelect(
	select: HTMLSelectElement,
	values: Array<{ value: string; label: string }>,
	current?: string,
): void {
	const wanted = values.map((v) => v.value).join("\u0000");
	if (select.dataset.filled !== wanted) {
		select.textContent = "";
		for (const v of values) {
			const option = document.createElement("option");
			option.value = v.value;
			option.textContent = v.label;
			select.appendChild(option);
		}
		select.dataset.filled = wanted;
	}
	if (current && select.value !== current) select.value = current;
}

function setRoute(msg: BrowserMessage): void {
	const onProject = Boolean(msg.route && msg.route !== "operator");
	whoEl.textContent = msg.label || "Operator";
	// Every leg runs at a level somebody chose, so there is always a level to
	// name. A leg that has not reported back yet is marked as asked-for
	// rather than stated as fact — the runtime may still clamp it.
	const name = msg.model_name || msg.model || "";
	let level = "";
	if (msg.thinking) {
		level = "thinking " + msg.thinking;
		if (!msg.thinking_confirmed) level += " (requested)";
	}
	modelEl.textContent = [name, level].filter(Boolean).join(" · ");
	lineEl.classList.toggle("project", onProject);

	fillSelect(
		routeSelect,
		[{ value: "operator", label: "Operator" }].concat(
			(msg.projects || []).map((id) => ({ value: id, label: id })),
		),
		msg.route || "operator",
	);

